      "id": 29,
      "session": 8,
      "level": "LT",
      "prompt": "Trình bày hệ thống văn bản pháp luật đang có hiệu lực điều chỉnh thương mại điện tử tại Việt Nam (số hiệu, thời điểm hiệu lực, nội dung chính). Vì sao phải kiểm tra hiệu lực trước khi trích dẫn?",
      "answer": "– Luật Thương mại điện tử 122/2025/QH15 (01/7/2026): đạo luật chuyên ngành đầu tiên — định danh người bán, trách nhiệm nền tảng, phát trực tiếp, xuyên biên giới, phát triển bền vững.\n\n– Luật Giao dịch điện tử 20/2023/QH15 (01/7/2024): giá trị pháp lý của thông điệp dữ liệu, chữ ký điện tử, hợp đồng điện tử, dịch vụ tin cậy.\n\n– Luật Bảo vệ quyền lợi người tiêu dùng 19/2023/QH15 (01/7/2024): chương riêng về giao dịch trên không gian mạng, trách nhiệm nền tảng số trung gian.\n\n– Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15 (01/01/2026): thay Nghị định 13/2023 — nguyên tắc xử lý, quyền chủ thể, thông báo vi phạm.\n\n– Luật An ninh mạng 116/2025/QH15 (01/7/2026): thay Luật ATTT mạng 2015 và Luật ANM 2018; an ninh dữ liệu; cấm dùng AI giả mạo, lừa đảo. Nghị định 52/2013, 85/2021 áp dụng chuyển tiếp trong phần không trái luật mới.\n\n– Lý do kiểm tra hiệu lực: khung pháp lý thay đổi trong 2025–2026; tài liệu trước 2025 vẫn dùng được phần phân tích nghiệp vụ nhưng phần dẫn chiếu văn bản phải đối chiếu lại; doanh nghiệp phải rà soát quy trình trong năm 2026.",
      "page": 70,
      "answerPage": 107
