      "answer": "– Sáu nhóm kiểm thử: chức năng theo luồng (đi hết luồng mua, kể cả ngoại lệ: hết hàng giữa lúc thanh toán, thanh toán thất bại, bấm quay lại); thiết bị thật (tối thiểu một Android, một iOS); hiệu năng (mạng di động, lần đầu truy cập); an toàn (HTTPS toàn site, không lộ lỗi chi tiết, kiểm tra dữ liệu phía máy chủ, không để thông tin đăng nhập trong mã); tuân thủ (đối chiếu danh mục buổi 8); sao lưu và phục hồi (phải thử phục hồi thật).\n\n– Vòng lặp cải tiến: đo (phễu theo nguồn — cài công cụ trước khi ra mắt) → chẩn đoán (bước có số người rơi tuyệt đối lớn nhất) → giả thuyết (thay đổi gì, chỉ số nào, mức bao nhiêu) → thử nghiệm A/B.\n\n– Quy tắc A/B: chia lưu lượng hai nhóm tương đương; mỗi lần chỉ thay đổi một thứ; xác định chỉ số và điều kiện dừng trước khi bắt đầu; với lưu lượng nhỏ, chênh lệch có thể chỉ do ngẫu nhiên.\n\n– Kết luận: ra mắt là điểm bắt đầu; không có dữ liệu nền thì không đánh giá được thay đổi.",
